trigger ContactRegion on Contact (before insert) {
    Set<Id> accIds = new Set<Id>();
    for (Contact c : Trigger.new) accIds.add(c.AccountId);
    Map<Id, Account> accs = new Map<Id, Account>(
        [SELECT Id, Industry FROM Account WHERE Id IN :accIds]);

    for (Contact c : Trigger.new) {
        Account a = accs.get(c.AccountId);
        if (a != null && a.Industry == 'Banking') {
            c.Region__c = [SELECT Region__c FROM Territory__c
                           WHERE Name = :c.MailingState LIMIT 1].Region__c;
        }
    }
}

