public class CaseService {
    public static void syncSiblings(Set<Id> caseIds) {
        List<Case> siblings = [SELECT Id, Priority FROM Case
                               WHERE ParentId IN (SELECT ParentId FROM Case WHERE Id IN :caseIds)
                               AND Id NOT IN :caseIds];
        for (Case c : siblings) c.Priority = 'High';
        update siblings;   // fires CaseSync again
    }
}

