export default class CaseBoard extends LightningElement {
    @track cases = [];
    filterText = '';

    get sortedGroups() {
        const rows = this.cases
            .filter(c => c.Subject.includes(this.filterText))
            .sort((a, b) => a.Priority.localeCompare(b.Priority));
        return groupByOwner(rows);
    }
    handleFilter(e) { this.filterText = e.target.value; }
}

